public Triple<String,String,Integer> forBoolUnaryOp(BoolUnaryOp b) {
    BoolExpr v = b.getBoolVal();
    Op op = b.getOp();
    return p(Naming.XL_BOOL, v.accept(this).getB() + Naming.ENTER + op.getText());
}

